"""Validators over depot run outputs (later batch).

Each validator vN(items) returns (passed: bool, measured: object).
"""

# Assumed inclusive bounds for supplier reliability (V9). The spec did not
# state a range; see ask_owner note. Adjust here if the spec differs.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def _capacity_violated(entry):
    """True when a warehouse's peak units exceed its capacity."""
    return entry["max_units"] > entry["capacity"]


def v7(items):
    """Every warehouse's capacity was respected across runs.

    items: iterable of entries {"wh": str, "capacity": int, "max_units": int}.

    measured: sorted list of warehouse names whose max_units exceeded
    capacity (empty when passed).
    """
    violating = set()
    for entry in items:
        if _capacity_violated(entry):
            violating.add(entry["wh"])
    measured = sorted(violating)
    return (len(measured) == 0, measured)


def _as_triples(rows):
    """Convert [sku, wh, qty] rows into a set of hashable tuples."""
    return {tuple(row) for row in rows}


def _unnotified_expiries(entry):
    """Expired triples in an entry that have no matching notification."""
    expired = _as_triples(entry["expired"])
    notified = _as_triples(entry["notified"])
    return expired - notified


def v8(items):
    """All expiries were notified.

    items: iterable of entries
        {"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}.
    An expiry counts as notified only if the exact [sku, wh, qty] triple
    appears in "notified" for the same entry.

    measured: sorted list of [sku, wh, qty] triples that were expired but
    never notified (empty when passed).
    """
    missing = set()
    for entry in items:
        missing |= _unnotified_expiries(entry)
    measured = sorted(list(triple) for triple in missing)
    return (len(measured) == 0, measured)


def _reliability_in_range(entry):
    """True when a supplier's reliability is within the configured bounds."""
    return RELIABILITY_MIN <= entry["reliability"] <= RELIABILITY_MAX


def v9(items):
    """Every supplier's reliability stayed in range.

    items: iterable of entries {"supplier": str, "reliability": int}.
    Range is RELIABILITY_MIN..RELIABILITY_MAX inclusive.

    measured: sorted list of supplier names with out-of-range reliability
    (empty when passed).
    """
    out_of_range = set()
    for entry in items:
        if not _reliability_in_range(entry):
            out_of_range.add(entry["supplier"])
    measured = sorted(out_of_range)
    return (len(measured) == 0, measured)
