<file path="tests/test_validators_later.py">
import unittest

from validators_later import v7, v8, v9


class TestV7(unittest.TestCase):
    def test_passes_when_all_within_capacity(self):
        items = [
            {"wh": "A", "capacity": 10, "max_units": 10},
            {"wh": "B", "capacity": 5, "max_units": 0},
        ]
        self.assertEqual(v7(items), (True, []))

    def test_reports_warehouses_over_capacity(self):
        items = [
            {"wh": "B", "capacity": 5, "max_units": 6},
            {"wh": "A", "capacity": 10, "max_units": 11},
            {"wh": "A", "capacity": 10, "max_units": 12},
            {"wh": "C", "capacity": 10, "max_units": 3},
        ]
        self.assertEqual(v7(items), (False, ["A", "B"]))

    def test_empty_input_passes(self):
        self.assertEqual(v7([]), (True, []))


class TestV8(unittest.TestCase):
    def test_passes_when_every_expiry_notified(self):
        items = [
            {
                "expired": [["s1", "w1", 4]],
                "notified": [["s1", "w1", 4], ["s2", "w1", 1]],
            },
        ]
        self.assertEqual(v8(items), (True, []))

    def test_reports_unnotified_expiries(self):
        items = [
            {
                "expired": [["s1", "w1", 4], ["s2", "w2", 3]],
                "notified": [["s1", "w1", 4]],
            },
        ]
        self.assertEqual(v8(items), (False, [["s2", "w2", 3]]))

    def test_quantity_must_match(self):
        items = [
            {"expired": [["s1", "w1", 4]], "notified": [["s1", "w1", 3]]},
        ]
        self.assertEqual(v8(items), (False, [["s1", "w1", 4]]))

    def test_empty_input_passes(self):
        self.assertEqual(v8([]), (True, []))


class TestV9(unittest.TestCase):
    def test_passes_at_bounds(self):
        items = [
            {"supplier": "x", "reliability": 0},
            {"supplier": "y", "reliability": 100},
        ]
        self.assertEqual(v9(items), (True, []))

    def test_reports_out_of_range_suppliers(self):
        items = [
            {"supplier": "z", "reliability": -1},
            {"supplier": "a", "reliability": 101},
            {"supplier": "m", "reliability": 50},
        ]
        self.assertEqual(v9(items), (False, ["a", "z"]))

    def test_empty_input_passes(self):
        self.assertEqual(v9([]), (True, []))


if __name__ == "__main__":
    unittest.main()
</file>

<notes>
- V7: a warehouse is violating if any of its entries has max_units > capacity. The measured value is the sorted list of such warehouse names. Equal to capacity passes.
- V8: "notified" is matched by the exact [sku, wh, qty] triple within the same entry. A quantity mismatch counts as not notified. If the spec means matching on (sku, wh) only, this needs to change.
- V9: the spec does not give a reliability range. I assumed 0 to 100 inclusive, set as RELIABILITY_MIN and RELIABILITY_MAX at the top of the module. This is an assumption, not confirmed.
- Tests use stdlib unittest and assume they run from the repository root so that `validators_later` is importable. I did not run them.
- I did not modify `validators.py`.

Question for the owner: what is the valid reliability range for V9 (inclusive bounds), and should V8 match expiries on the exact triple or on (sku, wh)?
</notes>

